    review = read(PACKET+'/GRAPH_CALIBRATION_ASSEMBLY_ROOT_REVIEW.md')
    need(sha(acceptance) == status['source_assembly_root_acceptance_sha256'] and sha(review) == status['source_assembly_root_review_sha256'], 'Assembly root review changed')
    scope = json.loads(acceptance)
    need(scope == status['source_review_coverage_verbatim'] and scope['freeze_sha256'] == SOURCE_FREEZE_SHA and scope['root_review_sha256'] == sha(review), 'Assembly acceptance scope differs')
